tape( 'the function returns a reference to the output array', function test( t ) {
	var condition;
	var out;
	var ret;
	var a;
	var b;

	condition = [ 1, 0 ];
	a = [ 1.0, 2.0, 3.0, 4.0 ];
	b = [ 5.0, 6.0, 7.0, 8.0 ];
	out = [ 0.0, 0.0, 0.0, 0.0 ];

	ret = gwhereRows( 'no-transpose', 'no-transpose', 2, 2, condition, 1, 0, a, 2, 1, 0, b, 2, 1, 0, out, 2, 1, 0 );

	t.strictEqual( ret, out, 'returns expected value' );

	t.end();
});

tape( 'the function takes rows based on a condition (row-major, no-transpose, no-transpose)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var b;

	data = rntantb;

	a = copy( data.A );
	b = copy( data.B );
	out = zeros( data.out_expected.length );

	expected = data.out_expected;

	gwhereRows( data.transA, data.transB, data.M, data.N, data.condition, 1, 0, a, data.lda, 1, 0, b, data.ldb, 1, 0, out, data.ldo, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

